def valid_date(date):
    """Validate a date string based on specific rules."""
    if not date:
        return False

    try:
        mm, dd, yyyy = map(int, date.split('-'))
    except ValueError:
        return False

    if not (1 <= mm <= 12):
        return False

    if mm in [1, 3, 5, 7, 8, 10, 12]:
        max_days = 31
    elif mm in [4, 6, 9, 11]:
        max_days = 30
    else:  # February
        max_days = 29

    if not (1 <= dd <= max_days):
        return False

    return True
